function validate([root]) {
  const values = root.filter(v => v !== null);
  if (values.length < 2) return 'The tree needs at least 2 nodes.';
  if (values.length > 5000) return 'The tree has at most 5000 nodes.';
  if (values.some(v => v < 0 || v > 100000)) return 'Every node value is between 0 and 100000.';
  return null;
}

