function maxAncestorDiff(root) {
  function dfs(node, low, high) {
    if (node === null) {
      return high - low;
    }
    const nextLow = Math.min(low, node.val);
    const nextHigh = Math.max(high, node.val);
    const leftDiff = dfs(node.left, nextLow, nextHigh);
    const rightDiff = dfs(node.right, nextLow, nextHigh);
    return Math.max(leftDiff, rightDiff);
  }
  return dfs(root, root.val, root.val);
}

