function maxAncestorDiff(root) {
  // List every node, then compare each one with every node in its subtree.
  const all = [root];
  for (let i = 0; i < all.length; i++) {
    if (all[i].left) all.push(all[i].left);
    if (all[i].right) all.push(all[i].right);
  }
  let best = 0;
  for (const a of all) {
    const stack = [];
    if (a.left) stack.push(a.left);
    if (a.right) stack.push(a.right);
    while (stack.length) {
      const b = stack.pop();
      best = Math.max(best, Math.abs(a.val - b.val));
      if (b.left) stack.push(b.left);
      if (b.right) stack.push(b.right);
    }
  }
  return best;
}

